package main

import (
	"fmt"
	"runtime"
	"strings"
)

// openCommand URL ni standart brauzerda ochadigan buyruqni qaytaradi.
func openCommand(goos, url string) []string {
	switch goos {
	case "windows":
		return []string{"rundll32", "url.dll,FileProtocolHandler", url}
	case "darwin":
		return []string{"open", url}
	default: // linux, freebsd, openbsd ...
		return []string{"xdg-open", url}
	}
}

func main() {
	url := "https://go.dev"
	fmt.Println("joriy:", strings.Join(openCommand(runtime.GOOS, url), " "))
	for _, goos := range []string{"darwin", "linux", "freebsd"} {
		fmt.Printf("%-7s: %s\n", goos, strings.Join(openCommand(goos, url), " "))
	}
}

