import "fmt"

type target struct{ goos, goarch string }

// binaryName release faylining nomini yasaydi.
func binaryName(app string, t target) string {
	name := fmt.Sprintf("%s-%s-%s", app, t.goos, t.goarch)
	switch {
	case t.goos == "windows":
		name += ".exe"
	case t.goarch == "wasm":
		name += ".wasm"
	}
	return name
}

