	}
}

package main

import (
	"cmp"
	"fmt"
	"slices"
	"strings"
)

// go tool dist list (Go 1.27.2)
var ports = strings.Fields(`
aix/ppc64 android/386 android/amd64 android/arm android/arm64
darwin/amd64 darwin/arm64 dragonfly/amd64 freebsd/386 freebsd/amd64
freebsd/arm freebsd/arm64 illumos/amd64 ios/amd64 ios/arm64 js/wasm
linux/386 linux/amd64 linux/arm linux/arm64 linux/loong64 linux/mips
linux/mips64 linux/mips64le linux/mipsle linux/ppc64 linux/ppc64le
linux/riscv64 linux/s390x netbsd/386 netbsd/amd64 netbsd/arm netbsd/arm64
openbsd/386 openbsd/amd64 openbsd/arm openbsd/arm64 openbsd/ppc64
openbsd/riscv64 plan9/386 plan9/amd64 plan9/arm solaris/amd64 wasip1/wasm
windows/386 windows/amd64 windows/arm64
`)

func main() {
	byOS := map[string][]string{}
	arches := map[string]bool{}
	for _, p := range ports {
		goos, goarch, _ := strings.Cut(p, "/")
		byOS[goos] = append(byOS[goos], goarch)
		arches[goarch] = true
	}
	fmt.Println("juftliklar:", len(ports), "| OS:", len(byOS), "| arxitektura:", len(arches))

	names := make([]string, 0, len(byOS))
	for goos := range byOS {
		names = append(names, goos)
	}
	slices.SortFunc(names, func(a, b string) int {
		return cmp.Or(cmp.Compare(len(byOS[b]), len(byOS[a])), cmp.Compare(a, b))
	})
	for _, goos := range names[:3] {
		fmt.Printf("%-8s %2d ta\n", goos, len(byOS[goos]))
	}
	fmt.Println("windows:", byOS["windows"])
}

