package main

import (
	"fmt"
	"go/build/constraint"
	"slices"
	"strings"
)

var unixOS = []string{"aix", "android", "darwin", "dragonfly", "freebsd",
	"illumos", "ios", "linux", "netbsd", "openbsd", "solaris"}

// tags maqsad uchun yoqiladigan teglar (soddalashtirilgan).
func tags(goos, goarch string, extra ...string) map[string]bool {
	set := map[string]bool{goos: true, goarch: true, "gc": true}
	if slices.Contains(unixOS, goos) {
		set["unix"] = true
	}
	switch goos {
	case "android":
		set["linux"] = true
	case "ios":
		set["darwin"] = true
	}
	for _, t := range extra {
		set[t] = true
	}
	return set
}

func main() {
	var exprs []constraint.Expr
	for _, line := range []string{"//go:build unix", "//go:build linux",
		"//go:build darwin && !ios", "//go:build integration || e2e"} {
		e, _ := constraint.Parse(line)
		exprs = append(exprs, e)
	}
	targets := []struct {
		name string
		set  map[string]bool
	}{
		{"linux/amd64", tags("linux", "amd64")},
		{"android/arm64", tags("android", "arm64")},
		{"darwin/arm64", tags("darwin", "arm64")},
		{"ios/arm64", tags("ios", "arm64")},
		{"windows/amd64+e2e", tags("windows", "amd64", "e2e")},
	}
	for _, t := range targets {
		var matched []string
		for _, e := range exprs {
			if e.Eval(func(tag string) bool { return t.set[tag] }) {
				matched = append(matched, e.String())
			}
		}
		fmt.Printf("%-18s %s\n", t.name+":", strings.Join(matched, "; "))
	}
}

package main

import (
	"fmt"
	"go/build/constraint"
)

// amd64Tags GOAMD64 darajasi uchun yoqiladigan teglar.
func amd64Tags(level int) map[string]bool {
	set := map[string]bool{"amd64": true}
	for v := 1; v <= level; v++ {
		set[fmt.Sprintf("amd64.v%d", v)] = true
	}
	return set
}

func main() {
	fast, _ := constraint.Parse("//go:build amd64.v3")
	generic, _ := constraint.Parse("//go:build !amd64.v3")
	for level := 1; level <= 4; level++ {
		set := amd64Tags(level)
		has := func(tag string) bool { return set[tag] }
		file := "sum_generic.go"
		if fast.Eval(has) {
			file = "sum_avx2.go"
		}
		fmt.Printf("GOAMD64=v%d -> %s (generic sharti: %v)\n", level, file, generic.Eval(has))
	}
}

