package main

import (
	"bufio"
	"fmt"
	"go/build/constraint"
	"strings"
)

// findConstraint shartni faqat package qatorigacha qidiradi.
func findConstraint(src string) string {
	sc := bufio.NewScanner(strings.NewReader(src))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		switch {
		case strings.HasPrefix(line, "package "):
			return "shart yo'q (package ga yetdik)"
		case constraint.IsGoBuild(line):
			return "topildi: " + line
		}
	}
	return "shart yo'q"
}

func main() {
	good := "// Copyright 2026 Shop\n\n//go:build linux\n\npackage netx\n"
	late := "package netx\n\n//go:build linux\n"
	doc := "// Package netx tarmoq yordamchilari.\npackage netx\n"
	for _, src := range []string{good, late, doc} {
		fmt.Println(findConstraint(src))
	}
}

