func main() {
	dir, err := os.MkdirTemp("", "suffix")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer os.RemoveAll(dir)

	names := []string{"main.go", "net_linux.go", "net_windows_amd64.go",
		"net_arm64.go", "linux.go", "_draft.go", "util_test.go"}
	for _, n := range names {
		os.WriteFile(filepath.Join(dir, n), []byte("package main\n"), 0o644)
	}
	for _, t := range [][2]string{{"linux", "amd64"}, {"windows", "amd64"}, {"darwin", "arm64"}} {
		ctx := build.Default
		ctx.GOOS, ctx.GOARCH = t[0], t[1]
		var picked []string
		for _, n := range names {
			if ok, _ := ctx.MatchFile(dir, n); ok {
				picked = append(picked, n)
			}
		}
		fmt.Printf("%s/%s: %v\n", t[0], t[1], picked)
	}
}

package main

import (
	"fmt"
	"go/build"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "tags")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer os.RemoveAll(dir)
	files := map[string]string{
		"main.go":      "package main\n",
		"mode_dev.go":  "//go:build !prod\n\npackage main\n",
		"mode_prod.go": "//go:build prod\n\npackage main\n",
		"unix.go":      "//go:build unix\n\npackage main\n",
		"gen.go":       "//go:build ignore\n\npackage main\n",
	}
	for name, src := range files {
		os.WriteFile(filepath.Join(dir, name), []byte(src), 0o644)
	}
	show := func(goos string, tags ...string) {
		ctx := build.Default
		ctx.GOOS = goos
		ctx.BuildTags = tags
		pkg, err := ctx.ImportDir(dir, 0)
		if err != nil {
			fmt.Println("xato:", err)
			return
		}
		fmt.Printf("GOOS=%s tags=%v\n", goos, tags)
		fmt.Println("  GoFiles:       ", pkg.GoFiles)
		fmt.Println("  IgnoredGoFiles:", pkg.IgnoredGoFiles)
	}
	show("windows")
	show("linux", "prod")
}

