package main

import (
	"fmt"
	"time"
)

// CI: -X main.buildTime=$(git log -1 --format=%cI) yoki $(date -u +%Y-%m-%dT%H:%M:%SZ)
var buildTime = "2026-01-15T10:30:00Z"

func main() {
	t, err := time.Parse(time.RFC3339, buildTime)
	if err != nil {
		fmt.Println("build vaqti noma'lum:", buildTime)
		return
	}
	fmt.Println("qurilgan:", t.Format("02.01.2006 15:04 MST"))
	fmt.Println("hafta kuni:", t.Weekday())

	bad := "15/01/2026"
	if _, err := time.Parse(time.RFC3339, bad); err != nil {
		fmt.Println("noto'g'ri format rad etildi:", bad)
	}
}

