func hot(n int) int {
	total := 0
	for i := range n {
		total += len(strings.Repeat("go", i%32))
	}
	return total
}

func main() {
	dir, err := os.MkdirTemp("", "pgo")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "default.pgo")

	f, err := os.Create(path)
	if err != nil {
		fmt.Println(err)
		return
	}
	if err := pprof.StartCPUProfile(f); err != nil {
		fmt.Println(err)
		return
	}
	sum := 0
	for range 200 {
		sum += hot(5000)
	}
	pprof.StopCPUProfile()
	f.Close()

	data, _ := os.ReadFile(path)
	fmt.Println("natija:", sum)
	fmt.Println("profil gzip formatida:", bytes.HasPrefix(data, []byte{0x1f, 0x8b}))
	fmt.Println("fayl:", filepath.Base(path))
}

