	dist := []artifact{
		{"shop-linux-amd64", 14_811_320, 9_830_560},
		{"shop-linux-arm64", 14_026_904, 9_437_368},
		{"shop-windows-amd64.exe", 15_204_864, 10_158_080},
		{"shop-darwin-arm64", 19_398_706, 13_107_408},
	}
	over := 0
	for _, a := range dist {
		saved := 100 * float64(a.plain-a.strip) / float64(a.plain)
		status := "OK"
		if a.strip > budget {
			status = "BYUDJETDAN KATTA"
			over++
		}
		fmt.Printf("%-24s %9s -> %9s (-%.0f%%) %s\n", a.name, mib(a.plain), mib(a.strip), saved, status)
	}
	fmt.Printf("byudjet %s, oshganlar: %d\n", mib(budget), over)
}

