	for _, a := range accounts { // vet: range var a copies lock: main.Account contains sync.Mutex
		a.mu.Lock()
		a.balance += 10
		a.mu.Unlock()
	}
	fmt.Println("range nusxa:", accounts[0].balance, accounts[1].balance)

	// To'g'ri: indeks orqali asl elementni o'zgartiramiz
	for i := range accounts {
