// sync.WaitGroup ichida ham xuddi shunday noCopy maydoni bor.
type noCopy struct{}

func (*noCopy) Lock()   {}
func (*noCopy) Unlock() {}

type Client struct {
	_    noCopy // xotira olmaydi, faqat vet uchun
	name string
	hits int
}

func NewClient(name string) *Client { return &Client{name: name} }

func (c *Client) Hit() { c.hits++ }

func main() {
	c := NewClient("api")
	c.Hit()

	snapshot := *c // vet: assignment copies lock value to snapshot: main.Client contains main.noCopy
	c.Hit()

	fmt.Println(c.name, "hits:", c.hits, "| nusxada:", snapshot.hits)
	fmt.Println("noCopy o'lchami:", unsafe.Sizeof(noCopy{}))
}

