package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

const src = `package shop

func closeAll(files []File) {
	for _, f := range files {
		defer f.Close()
	}
}

func handle(f File) {
	defer f.Close()
	for i := 0; i < 3; i++ {
		go func() { defer done() }()
	}
}
`

func main() {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "shop.go", src, 0)
	if err != nil {
		fmt.Println(err)
		return
	}
	// Sikl ichidagi defer'larni qidiramiz; ichki funksiya (closure) — yangi qamrov
	var visit func(n ast.Node, inLoop bool)
	visit = func(n ast.Node, inLoop bool) {
		ast.Inspect(n, func(c ast.Node) bool {
			switch c := c.(type) {
			case *ast.ForStmt:
				visit(c.Body, true)
				return false
			case *ast.RangeStmt:
				visit(c.Body, true)
				return false
			case *ast.FuncLit:
				visit(c.Body, false)
				return false
			case *ast.DeferStmt:
				if inLoop {
					fmt.Printf("%s: defer sikl ichida — funksiya oxirigacha kutadi\n", fset.Position(c.Pos()))
				}
			}
			return true
		})
	}
	for _, decl := range file.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok {
			visit(fn.Body, false)
		}
	}
}

