const src = `package demo

type Config struct{ limit int }

func (c *Config) SetLimit(limit int) {
	limit = limit
}

func swap(a, b int) (int, int) {
	a, b = b, a
	return a, b
}

func main() {
	c := &Config{}
	c.limit = c.limit
	x := 1
	x = x + 0
}
`

func main() {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "demo.go", src, 0)
	if err != nil {
		fmt.Println(err)
		return
	}
	// Tiplarni tekshiramiz: qaysi identifikator qaysi obyektga tegishli ekanini bilish uchun
	info := &types.Info{Uses: map[*ast.Ident]types.Object{}}
	conf := types.Config{Error: func(error) {}} // "x declared and not used" kabi xatolarni e'tiborsiz qoldiramiz
	conf.Check("demo", fset, []*ast.File{file}, info)

	ast.Inspect(file, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || as.Tok != token.ASSIGN || len(as.Lhs) != len(as.Rhs) {
			return true
		}
		for i := range as.Lhs {
			// Chap va o'ng tomon matni bir xil bo'lsa — o'z-o'ziga o'zlashtirish
			l, r := types.ExprString(as.Lhs[i]), types.ExprString(as.Rhs[i])
			if l == r && sameObject(info, as.Lhs[i], as.Rhs[i]) {
				fmt.Printf("%s: self-assignment of %s\n", fset.Position(as.Pos()), l)
			}
		}
		return true
	})
}

// sameObject: ikkala ifodaning oxirgi identifikatori bitta obyektni ko'rsatadimi
func sameObject(info *types.Info, a, b ast.Expr) bool {
	return info.Uses[lastIdent(a)] != nil && info.Uses[lastIdent(a)] == info.Uses[lastIdent(b)]
}

func lastIdent(e ast.Expr) *ast.Ident {
	switch e := e.(type) {
	case *ast.Ident:
		return e
	case *ast.SelectorExpr:
		return e.Sel
	}
	return nil
}

