const src = `package app

func Run(n int) {
	if n < 0 {
		panic("manfiy") //nolint:nopanic // init bosqichi: ishga tushmaslik kerak
	}
	if n == 0 {
		panic("nol") //nolint:nopanic
	}
	panic("boshqa")
}
`

// Analyzer — go/analysis.Analyzer ning juda soddalashtirilgan nusxasi
type Analyzer struct {
	Name string
	Run  func(f *ast.File, report func(token.Pos, string))
}

type Diag struct {
	Pos      token.Position
	Msg, Who string
}

var noPanic = &Analyzer{Name: "nopanic", Run: func(f *ast.File, report func(token.Pos, string)) {
	ast.Inspect(f, func(n ast.Node) bool {
		if c, ok := n.(*ast.CallExpr); ok {
			if id, ok := c.Fun.(*ast.Ident); ok && id.Name == "panic" {
				report(c.Pos(), "panic o'rniga xato qaytaring")
			}
		}
		return true
	})
}}

var nolintRe = regexp.MustCompile(`^//nolint:(\w+)(\s+//\s*\S.*)?$`)

func main() {
	fset := token.NewFileSet()
	file, _ := parser.ParseFile(fset, "app.go", src, parser.ParseComments)

	suppressed := map[int]string{} // 1. //nolint izohlari: qator → linter nomi
	var diags []Diag
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			if m := nolintRe.FindStringSubmatch(c.Text); m != nil {
				pos := fset.Position(c.Pos())
				suppressed[pos.Line] = m[1]
				if m[2] == "" { // nolintlint: sabab yozilmagan
					diags = append(diags, Diag{pos, "//nolint sababsiz", "nolintlint"})
				}
			}
		}
	}
	for _, a := range []*Analyzer{noPanic} { // 2. analizatorlar, bostirilganlarisiz
		a.Run(file, func(p token.Pos, msg string) {
			pos := fset.Position(p)
			if suppressed[pos.Line] != a.Name {
				diags = append(diags, Diag{pos, msg, a.Name})
			}
		})
	}
	// 3. fayldagi o'rni (qator:ustun) bo'yicha tartiblaymiz
	slices.SortFunc(diags, func(x, y Diag) int { return x.Pos.Offset - y.Pos.Offset })
	for _, d := range diags {
		fmt.Printf("%s: %s (%s)\n", d.Pos, d.Msg, d.Who)
	}
	fmt.Println(len(diags), "issues")
}

