// `go vet -json ./...` chiqishi (CI'da faylga yozilgan)
const vetJSON = `{
	"example.com/shop/api": {
		"printf": [{"posn": "/work/shop/api/handler.go:42:15", "message": "fmt.Sprintf format %d has arg id of wrong type string"}],
		"copylocks": [{"posn": "/work/shop/api/cache.go:18:9", "message": "Get passes lock by value: api.Cache contains sync.RWMutex"}]
	},
	"example.com/shop/db": {
		"lostcancel": [{"posn": "/work/shop/db/conn.go:27:7", "message": "the cancel function is not used on all paths (possible context leak)"}]
	}
}`

type finding struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

func main() {
	var report map[string]map[string][]finding // paket → analizator → topilmalar
	if err := json.Unmarshal([]byte(vetJSON), &report); err != nil {
		fmt.Println("xato:", err)
		return
	}
	type line struct{ file, pos, analyzer, msg string }
	var lines []line
	for _, pkg := range slices.Sorted(maps.Keys(report)) {
		for analyzer, items := range report[pkg] {
			for _, f := range items {
				// "/work/shop/api/handler.go:42:15" → fayl va qator:ustun
				i := strings.Index(f.Posn, ".go:") + 3
				rel, _ := filepath.Rel("/work/shop", f.Posn[:i])
				lines = append(lines, line{filepath.ToSlash(rel), f.Posn[i+1:], analyzer, f.Message})
			}
		}
	}
	slices.SortFunc(lines, func(a, b line) int { return cmp.Compare(a.file, b.file) })

	// GitHub Actions "workflow command": PR'da kod qatoriga izoh bo'lib chiqadi
	for _, l := range lines {
		lc := strings.SplitN(l.pos, ":", 2)
		fmt.Printf("::error file=%s,line=%s,col=%s,title=go vet (%s)::%s\n", l.file, lc[0], lc[1], l.analyzer, l.msg)
	}
	if len(lines) > 0 {
		fmt.Printf("%d ta muammo — job muvaffaqiyatsiz (exit 1)\n", len(lines))
	}
}

