package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// split — go generate argumentlarni shunday ajratadi: bo'shliq bo'yicha,
// "..." esa Go satri sifatida (strconv.Unquote) bitta argument bo'ladi
func split(line string) ([]string, error) {
	var words []string
	for {
		line = strings.TrimLeft(line, " \t")
		if line == "" {
			return words, nil
		}
		if line[0] == '"' {
			q, err := strconv.QuotedPrefix(line)
			if err != nil {
				return nil, errors.New("qo'shtirnoq yopilmagan")
			}
			w, _ := strconv.Unquote(q)
			words = append(words, w)
			line = line[len(q):]
			continue
		}
		i := strings.IndexAny(line, " \t")
		if i < 0 {
			i = len(line)
		}
		words = append(words, line[:i])
		line = line[i:]
	}
}

func main() {
	for _, args := range []string{
		`stringer -type=Color -output color_string.go`,
		`echo "ikki so'z" bitta`,
		`go run gen.go -title "Narxlar\tjadvali" -n=3`,
		`sh -c "ls *.proto | wc -l"`,
		`echo "yopilmagan`,
	} {
		words, err := split(args)
		if err != nil {
			fmt.Printf("%-46s → xato: %v\n", args, err)
			continue
		}
		fmt.Printf("%-46s → %d ta: %q\n", args, len(words), words)
	}
}

