// camel: "user_id" → "UserID" (Go uslubida qisqartmalar katta harf bilan)
func camel(s string) string {
	var b strings.Builder
	for part := range strings.SplitSeq(s, "_") {
		switch part {
		case "id", "url", "ip":
			b.WriteString(strings.ToUpper(part))
		default:
			b.WriteString(strings.ToUpper(part[:1]) + part[1:])
		}
	}
	return b.String()
}

var funcs = template.FuncMap{"camel": camel, "quote": strconv.Quote}

var tmpl = template.Must(template.New("cols").Funcs(funcs).Parse(`package db

// {{.Table}} jadvali ustunlari
const (
{{- range .Columns}}
	Col{{camel .}} = {{quote .}}
{{- end}}
)
`))

