// writeIfChanged — mazmun o'zgarmagan bo'lsa faylga tegmaydi:
// o'zgartirish vaqti saqlanadi, muharrir va build keshi bezovta bo'lmaydi
func writeIfChanged(path string, src []byte) (bool, error) {
	old, err := os.ReadFile(path)
	switch {
	case err == nil && bytes.Equal(old, src):
		return false, nil
	case err != nil && !errors.Is(err, fs.ErrNotExist):
		return false, err
	}
	return true, os.WriteFile(path, src, 0o644)
}

func main() {
	dir, _ := os.MkdirTemp("", "gen-*")
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "color_string.go")

	v1 := []byte("// Code generated by gen; DO NOT EDIT.\n\npackage a\n\nconst n = 3\n")
	v2 := []byte("// Code generated by gen; DO NOT EDIT.\n\npackage a\n\nconst n = 4\n")

	for i, src := range [][]byte{v1, v1, v2, v2} {
		changed, err := writeIfChanged(path, src)
		if err != nil {
			fmt.Println("xato:", err)
			return
		}
		status := "o'zgarmadi — yozilmadi"
		if changed {
			status = "yozildi"
		}
		fmt.Printf("%d-yurish: %s\n", i+1, status)
	}
}

