)

func main() {
	typeName := flag.String("type", "", "struct nomi")
	flag.Parse()
	// go generate o'rnatadi; generator paket papkasida ishga tushadi
	file, pkg := os.Getenv("GOFILE"), os.Getenv("GOPACKAGE")
	f, err := parser.ParseFile(token.NewFileSet(), file, nil, 0)
	if err != nil {
		log.Fatal(err)
	}
	var fields []string
	ast.Inspect(f, func(n ast.Node) bool {
		ts, ok := n.(*ast.TypeSpec)
		if !ok || ts.Name.Name != *typeName {
			return true
		}
		for _, fl := range ts.Type.(*ast.StructType).Fields.List {
			for _, name := range fl.Names {
				fields = append(fields, fmt.Sprintf("%q", name.Name))
			}
		}
		return false
	})
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by gen; DO NOT EDIT.\n\npackage %s\n\n", pkg)
	fmt.Fprintf(&b, "func (%s) Fields() []string { return []string{%s} }\n", *typeName, strings.Join(fields, ", "))
	src, err := format.Source(b.Bytes())
	if err != nil {
		log.Fatal(err)
	}
	out := strings.ToLower(*typeName) + "_fields.go"
	if err := os.WriteFile(out, src, 0o644); err != nil {
		log.Fatal(err)
	}
	fmt.Println("yozildi:", out)
}

