// treePrinter — ast.Visitor: har tugunda chaqiriladi, chuqurlikni o'zi saqlaydi
type treePrinter struct{ depth int }

func (p treePrinter) Visit(n ast.Node) ast.Visitor {
	if n == nil { // bolalari tugaganda Walk Visit(nil) ni chaqiradi
		return nil
	}
	label := ""
	if id, ok := n.(*ast.Ident); ok {
		label = " " + id.Name
	}
	fmt.Printf("%s%T%s\n", strings.Repeat("  ", p.depth), n, label)
	return treePrinter{p.depth + 1} // bolalar uchun yangi Visitor
}

