const src = `package store

func Open(path string) {
	if path == "" {
		panic("yo'l bo'sh")
	}
}

func MustLoad(id int) {
	defer func() {
		panic("ichki funksiyada")
	}()
}

var _ = func() int { panic("paket o'zgaruvchisida") }
`

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "store.go", src, 0)
	if err != nil {
		panic(err)
	}
	// PreorderStack (Go 1.25): f ga tugun bilan birga uning ota-onalari ham beriladi
	ast.PreorderStack(f, nil, func(n ast.Node, stack []ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if id, ok := call.Fun.(*ast.Ident); !ok || id.Name != "panic" {
			return true
		}
		where := "paket darajasi"
		for i := len(stack) - 1; i >= 0; i-- {
			if fn, ok := stack[i].(*ast.FuncDecl); ok {
				where = "func " + fn.Name.Name
				break
			}
		}
		fmt.Printf("%s: panic — %s (chuqurlik %d)\n", fset.Position(call.Pos()), where, len(stack))
		return true
	})
}

