// hasMarker — izoh guruhida "//gen:getters" qatori bormi
func hasMarker(doc *ast.CommentGroup) bool {
	if doc == nil {
		return false
	}
	for _, c := range doc.List {
		if strings.TrimSpace(c.Text) == "//gen:getters" {
			return true
		}
	}
	return false
}

func main() {
	f, err := parser.ParseFile(token.NewFileSet(), "model.go", src, parser.ParseComments)
	if err != nil {
		panic(err)
	}
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.TYPE {
			continue
		}
		for _, spec := range gd.Specs {
			ts := spec.(*ast.TypeSpec)
			// qavssiz "type X ..." da izoh GenDecl.Doc ga, qavs ichida — TypeSpec.Doc ga tushadi
			doc := ts.Doc
			if doc == nil && !gd.Lparen.IsValid() {
				doc = gd.Doc
			}
			st, isStruct := ts.Type.(*ast.StructType)
			if isStruct && hasMarker(doc) {
				fmt.Printf("generatsiya: %s (%d maydon)\n", ts.Name.Name, st.Fields.NumFields())
			} else {
				fmt.Printf("o'tkazildi:  %s\n", ts.Name.Name)
			}
		}
	}
}

