package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
)

// Go 1.18 gacha IntSet, StringSet... har biri generator bilan alohida yozilardi.
// Endi bitta generic tip yetarli — generatsiya kerak emas.
type Set[T comparable] struct{ m map[T]struct{} }

func NewSet[T comparable](items ...T) *Set[T] {
	s := &Set[T]{m: make(map[T]struct{})}
	for _, it := range items {
		s.Add(it)
	}
	return s
}

func (s *Set[T]) Add(v T) { s.m[v] = struct{}{} }

func (s *Set[T]) Has(v T) bool {
	_, ok := s.m[v]
	return ok
}

func (s *Set[T]) Len() int { return len(s.m) }

func (s *Set[T]) Union(o *Set[T]) *Set[T] {
	r := NewSet(slices.Collect(maps.Keys(s.m))...)
	for v := range o.m {
		r.Add(v)
	}
	return r
}

// Sorted — tartiblanadigan tiplar uchun alohida generic funksiya
func Sorted[T cmp.Ordered](s *Set[T]) []T {
	return slices.Sorted(maps.Keys(s.m))
}

func main() {
	ids := NewSet(3, 1, 2, 3, 1)
	tags := NewSet("go", "web").Union(NewSet("go", "sql"))

	fmt.Println("ids:", ids.Len(), ids.Has(2), ids.Has(7), Sorted(ids))
	fmt.Println("tags:", tags.Len(), Sorted(tags))
}

