)

const input = `package account

//gen:getters
type Account struct {
	number  string
	owner   string
	balance int64
	tags    []string
}

type audit struct{ log []string }
`

var tmpl = template.Must(template.New("getters").Funcs(template.FuncMap{
	"export": func(s string) string { return strings.ToUpper(s[:1]) + s[1:] },
}).Parse("// Code generated by gettergen; DO NOT EDIT.\n\npackage {{.Package}}\n" + `{{range .Types}}{{$t := .Name}}{{range .Fields}}
// {{export .Name}} {{.Name}} maydonini qaytaradi.
func (x *{{$t}}) {{export .Name}}() {{.Type}} { return x.{{.Name}} }
{{end}}{{end}}`))

type Field struct{ Name, Type string }
type Type struct {
	Name   string
	Fields []Field
}

func main() {
	// 1. Kirish: Go kodi → AST
	f, err := parser.ParseFile(token.NewFileSet(), "account.go", input, parser.ParseComments)
	if err != nil {
		panic(err)
	}
	// 2. Tahlil: //gen:getters belgilangan struct'larni yig'ish
	var list []Type
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Doc == nil || !slices.ContainsFunc(gd.Doc.List, func(c *ast.Comment) bool {
			return c.Text == "//gen:getters"
		}) {
			continue
		}
		ts := gd.Specs[0].(*ast.TypeSpec)
		t := Type{Name: ts.Name.Name}
		for _, fl := range ts.Type.(*ast.StructType).Fields.List {
			for _, n := range fl.Names {
				t.Fields = append(t.Fields, Field{n.Name, types.ExprString(fl.Type)})
			}
		}
		list = append(list, t)
	}
	// 3. Shablon → 4. format.Source → natija
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, map[string]any{"Package": f.Name.Name, "Types": list}); err != nil {
		panic(err)
	}
	src, err := format.Source(buf.Bytes())
	if err != nil {
		panic(fmt.Sprintf("%v\n%s", err, buf.Bytes()))
	}
	fmt.Print(string(src))
}

