	"strings"
)

const input = `package shop

type Store interface {
	Get(id int) (string, error)
	Save(id int, name string) error
	Count() int
}
`

func main() {
	f, err := parser.ParseFile(token.NewFileSet(), "store.go", input, 0)
	if err != nil {
		panic(err)
	}
	ts := f.Decls[0].(*ast.GenDecl).Specs[0].(*ast.TypeSpec)
	iface := ts.Type.(*ast.InterfaceType)
	mock := ts.Name.Name + "Mock"

	var fields, methods bytes.Buffer
	for _, m := range iface.Methods.List {
		name := m.Names[0].Name
		ft := m.Type.(*ast.FuncType)
		sig := strings.TrimPrefix(types.ExprString(ft), "func") // "(id int) (string, error)"
		var args []string
		for _, p := range ft.Params.List {
			for _, n := range p.Names {
				args = append(args, n.Name)
			}
		}
		ret := ""
		if ft.Results != nil {
			ret = "return "
		}
		fmt.Fprintf(&fields, "%sFunc func%s\n", name, sig)
		fmt.Fprintf(&methods, "\nfunc (m *%s) %s%s {\n\tm.Calls = append(m.Calls, %q)\n\t%sm.%sFunc(%s)\n}\n",
			mock, name, sig, name, ret, name, strings.Join(args, ", "))
	}

	var out bytes.Buffer
	fmt.Fprintf(&out, "// Code generated by minimock; DO NOT EDIT.\n\npackage %s\n\n", f.Name.Name)
	fmt.Fprintf(&out, "// %s — %s interfeysining soxta amalga oshirilishi.\n", mock, ts.Name.Name)
	fmt.Fprintf(&out, "type %s struct {\n%sCalls []string\n}\n", mock, fields.String())
	out.Write(methods.Bytes())
	fmt.Fprintf(&out, "\n// kompilyatsiya vaqtidagi tekshiruv: mock interfeysga mos\nvar _ %s = (*%s)(nil)\n", ts.Name.Name, mock)

	src, err := format.Source(out.Bytes())
	if err != nil {
		panic(err)
	}
	fmt.Print(string(src))
}

