package main

import (
	"bytes"
	"fmt"
	"go/format"
	"slices"
	"strings"
)

// generate — generatorning asosiy funksiyasi: kirish → Go kodi
func generate(names []string) []byte {
	var b bytes.Buffer
	b.WriteString("// Code generated by rolegen; DO NOT EDIT.\n\npackage auth\n\nvar roles = []string{\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%q,\n", n)
	}
	b.WriteString("}\n")
	src, _ := format.Source(b.Bytes())
	return src
}

// check — CI rejimi: diskdagi fayl yangi natija bilan bir xilmi
func check(file string, onDisk, fresh []byte) bool {
	if bytes.Equal(onDisk, fresh) {
		fmt.Println("✔", file, "— yangi")
		return true
	}
	oldLines := strings.Split(string(onDisk), "\n")
	newLines := strings.Split(string(fresh), "\n")
	fmt.Println("✖", file, "eskirgan — `go generate ./...` ni ishga tushiring:")
	for _, l := range oldLines {
		if !slices.Contains(newLines, l) {
			fmt.Println("  -", strings.TrimSpace(l))
		}
	}
	for _, l := range newLines {
		if !slices.Contains(oldLines, l) {
			fmt.Println("  +", strings.TrimSpace(l))
		}
	}
	return false
}

func main() {
	committed := generate([]string{"admin", "editor"}) // repozitoriydagi versiya
	input := []string{"admin", "editor"}

	check("roles_gen.go", committed, generate(input))

	input = append(input, "viewer") // kimdir kirishni o'zgartirdi, generate'ni unutdi
	if !check("roles_gen.go", committed, generate(input)) {
		fmt.Println("CI: os.Exit(1) — build to'xtatiladi")
	}
