// Build paytida: go build -ldflags "-X main.version=1.4.2 -X main.commit=a1b2c3d"
var (
	version = "dev"
	commit  = ""
)

// revision commit'ni avval ldflags'dan, keyin build ma'lumotidan (vcs.revision) oladi.
func revision() string {
	if commit != "" {
		return commit
	}
	if info, ok := debug.ReadBuildInfo(); ok {
		for _, s := range info.Settings {
			if s.Key == "vcs.revision" && len(s.Value) >= 7 {
				return s.Value[:7]
			}
		}
	}
	return "unknown"
}

func versionString() string {
	return fmt.Sprintf("shop %s (commit %s, %s)", version, revision(), runtime.Version())
}

