// aks holda fn bilan o'giradi va xatoga kalit nomi hamda qiymatni qo'shadi.
func parse[T any](getenv func(string) string, key string, def T, fn func(string) (T, error)) (T, error) {
	v := getenv(key)
	if v == "" {
		return def, nil
	}
	out, err := fn(v)
	if err != nil {
		return def, fmt.Errorf("%s=%q: %w", key, v, err)
	}
	return out, nil
}

