	_, err := parse(getenv, "PORT", 8080, strconv.Atoi)
	fmt.Println(err)
	_, err = parse(getenv, "READ_TIMEOUT", 5*time.Second, time.ParseDuration)
	fmt.Println(err)
	_, err = parse(getenv, "DEBUG", false, strconv.ParseBool)
	fmt.Println(err)
	n, err := parse(getenv, "WORKERS", 4, strconv.Atoi) // berilmagan — standart
