type Config struct {
	Port            int
	Env             string
	Debug           bool
	ShutdownTimeout time.Duration
}

var envs = []string{"development", "staging", "production"}

// Validate qiymatlarning o'zaro mosligini ham tekshiradi.
func (c Config) Validate() error {
	var errs []error
	if c.Port < 1 || c.Port > 65535 {
		errs = append(errs, fmt.Errorf("PORT 1..65535 oralig'ida bo'lishi kerak, %d berildi", c.Port))
	}
	if !slices.Contains(envs, c.Env) {
		errs = append(errs, fmt.Errorf("APP_ENV quyidagilardan biri bo'lsin: %v, %q berildi", envs, c.Env))
	}
	if c.Env == "production" && c.Debug {
		errs = append(errs, errors.New("production'da DEBUG yoqilmasin"))
	}
	if c.ShutdownTimeout >= 30*time.Second {
		errs = append(errs, errors.New("SHUTDOWN_TIMEOUT Kubernetes grace muddatidan (30s) qisqa bo'lsin"))
	}
	return errors.Join(errs...)
}

func main() {
	configs := []Config{
		{Port: 8080, Env: "production", ShutdownTimeout: 20 * time.Second},
		{Port: 8080, Env: "production", Debug: true, ShutdownTimeout: 20 * time.Second},
		{Port: 70000, Env: "prod", ShutdownTimeout: 45 * time.Second},
	}
	for i, c := range configs {
		if err := c.Validate(); err != nil {
			fmt.Printf("%d-konfiguratsiya: xato\n%v\n", i+1, err)
			continue
		}
		fmt.Printf("%d-konfiguratsiya: ok\n", i+1)
	}
}

