// bo'sh elementlar tashlanadi, takrorlar olib tashlanadi, tartib saqlanadi.
func list(v string) []string {
	var out []string
	seen := map[string]bool{}
	for item := range strings.SplitSeq(v, ",") {
		item = strings.TrimSpace(item)
		if item == "" || seen[item] {
			continue
		}
		seen[item] = true
		out = append(out, item)
	}
	return out
}

