import (
	"fmt"
	"strconv"
	"strings"
)

// parseSize GOMEMLIMIT uslubidagi hajmni baytga o'giradi: 512MiB, 1GiB, 64KiB, 1000.
func parseSize(s string) (int64, error) {
	orig := s
	units := []struct {
		suffix string
		mult   int64
	}{
		{"TiB", 1 << 40}, {"GiB", 1 << 30}, {"MiB", 1 << 20}, {"KiB", 1 << 10}, {"B", 1},
	}
	mult := int64(1)
	for _, u := range units {
		if rest, ok := strings.CutSuffix(s, u.suffix); ok {
			s, mult = rest, u.mult
			break
		}
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		return 0, fmt.Errorf("hajm noto'g'ri: %q (masalan 512MiB)", orig)
	}
	return n * mult, nil
}

func main() {
	for _, v := range []string{"512MiB", "1GiB", "64KiB", "1000", "2GB"} {
		n, err := parseSize(v)
		if err != nil {
			fmt.Println(v, "->", err)
			continue
		}
		fmt.Printf("%-6s -> %d bayt\n", v, n)
	}
}

