// secret KEY_FILE (Docker/Kubernetes secret fayli) yoki KEY dan o'qiydi.
func secret(getenv func(string) string, key string) (string, error) {
	if path := getenv(key + "_FILE"); path != "" {
		b, err := os.ReadFile(path)
		if err != nil {
			return "", fmt.Errorf("%s_FILE: %w", key, err)
		}
		return strings.TrimSpace(string(b)), nil // oxiridagi \n ni olib tashlaymiz
	}
	if v := getenv(key); v != "" {
		return v, nil
	}
	return "", fmt.Errorf("%s yoki %s_FILE berilishi kerak", key, key)
}

func main() {
	dir, _ := os.MkdirTemp("", "secrets") // /run/secrets ni taqlid qilamiz
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "db_password")
	os.WriteFile(path, []byte("s3cr3t\n"), 0o400)

	env := map[string]string{"DB_PASSWORD_FILE": path}
	getenv := func(k string) string { return env[k] }

	pw, err := secret(getenv, "DB_PASSWORD")
	fmt.Printf("fayldan: %d belgi, xato: %v\n", len(pw), err)

	env["DB_PASSWORD_FILE"] = filepath.Join(dir, "yoq")
	_, err = secret(getenv, "DB_PASSWORD")
	fmt.Println("fayl topilmadi:", errors.Is(err, fs.ErrNotExist))

	delete(env, "DB_PASSWORD_FILE")
	_, err = secret(getenv, "DB_PASSWORD")
	fmt.Println(err)
}

