		fmt.Printf("  %-8s %d %s\n", path, rec.Code, strings.TrimSpace(rec.Body.String()))
	}

	fmt.Println("ishga tushish:")
	probe("/healthz")
	probe("/readyz")

	// keshni to'ldirish, migratsiyani tekshirish, ulanishlar pulini ochish...
	ready.Store(true)

	fmt.Println("isinish tugadi:")
	probe("/healthz")
	probe("/readyz")
}

