import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
)

type check struct {
	name string
	fn   func(context.Context) error
}

// readyz barcha tekshiruvlarni parallel, umumiy timeout bilan bajaradi.
func readyz(timeout time.Duration, checks ...check) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx, cancel := context.WithTimeout(r.Context(), timeout)
		defer cancel()

		var mu sync.Mutex
		var wg sync.WaitGroup
		results, status := map[string]string{}, http.StatusOK
		for _, c := range checks {
			wg.Go(func() {
				res := "ok"
				if err := c.fn(ctx); err != nil {
					res = err.Error()
				}
				mu.Lock()
				defer mu.Unlock()
				results[c.name] = res
				if res != "ok" {
					status = http.StatusServiceUnavailable
				}
			})
		}
		wg.Wait()
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		json.NewEncoder(w).Encode(results) // map kalitlari tartiblab yoziladi
	}
}

func main() {
	db := check{"db", func(ctx context.Context) error { return nil }}
	cache := check{"cache", func(ctx context.Context) error {
		select { // osilib qolgan Redis: javob 2 soniyada keladi
		case <-time.After(2 * time.Second):
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	}}

	rec := httptest.NewRecorder()
	readyz(100*time.Millisecond, db, cache).ServeHTTP(rec, httptest.NewRequest("GET", "/readyz", nil))
	fmt.Print(rec.Code, " ", rec.Body.String())
}

