import (
	"context"
	"errors"
	"fmt"
	"time"
)

// waitFor bog'liqlik (baza, broker) tayyor bo'lguncha eksponensial kutish bilan urinadi.
func waitFor(ctx context.Context, name string, attempts int, delay time.Duration, try func(context.Context) error) error {
	for i := 1; ; i++ {
		err := try(ctx)
		if err == nil {
			fmt.Printf("%s: tayyor (%d-urinish)\n", name, i)
			return nil
		}
		if i == attempts {
			return fmt.Errorf("%s: %d urinishdan keyin ham tayyor emas: %w", name, attempts, err)
		}
		fmt.Printf("%s: %d-urinish xato (%v), %v kutamiz\n", name, i, err, delay)
		select {
		case <-time.After(delay):
		case <-ctx.Done():
			return ctx.Err()
		}
		delay *= 2
	}
}

func main() {
	ctx := context.Background()
	refused := errors.New("connection refused")

	calls := 0
	postgres := func(context.Context) error { // compose'da baza bizdan kechroq ko'tariladi
		calls++
		if calls < 4 {
			return refused
		}
		return nil
	}
	fmt.Println(waitFor(ctx, "postgres", 5, 10*time.Millisecond, postgres))

	broken := func(context.Context) error { return refused }
	fmt.Println(waitFor(ctx, "redis", 2, 10*time.Millisecond, broken))
}

