package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// gomaxprocsFor Go runtime'ining qoidasini takrorlaydi:
// limit = quota/period, kasr yuqoriga yaxlitlanadi, kamida 2, lekin CPU sonidan ko'p emas.
// cpu.max fayli (cgroup v2): "<quota> <period>" yoki "max <period>".
func gomaxprocsFor(cpuMax string, ncpu int) int {
	f := strings.Fields(cpuMax)
	if len(f) != 2 || f[0] == "max" {
		return ncpu // limit yo'q
	}
	quota, err1 := strconv.ParseFloat(f[0], 64)
	period, err2 := strconv.ParseFloat(f[1], 64)
	if err1 != nil || err2 != nil || period <= 0 {
		return ncpu
	}
	limit := max(math.Ceil(quota/period), 2)
	return min(ncpu, int(limit))
}

func main() {
	const ncpu = 8 // xostdagi CPU soni
	cases := []struct{ flag, cpuMax string }{
		{"(limitsiz)", "max 100000"},
		{"--cpus=0.5", "50000 100000"},
		{"--cpus=1.5", "150000 100000"},
		{"--cpus=3.5", "350000 100000"},
		{"--cpus=16", "1600000 100000"},
	}
	for _, c := range cases {
		fmt.Printf("%-11s cpu.max=%-17q GOMAXPROCS=%d\n", c.flag, c.cpuMax, gomaxprocsFor(c.cpuMax, ncpu))
	}
}

