// memLimitFromCgroup cgroup v2 memory.max faylidan limitning ratio qismini hisoblaydi.
func memLimitFromCgroup(path string, ratio float64) (int64, bool) {
	b, err := os.ReadFile(path)
	if err != nil {
		return 0, false // cgroup yo'q (konteyner emas)
	}
	s := strings.TrimSpace(string(b))
	if s == "max" {
		return 0, false // limit qo'yilmagan
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n <= 0 {
		return 0, false
	}
	return int64(float64(n) * ratio), true
}

func main() {
	dir, _ := os.MkdirTemp("", "cgroup") // /sys/fs/cgroup ni taqlid qilamiz
	defer os.RemoveAll(dir)
	file := filepath.Join(dir, "memory.max")

	for _, content := range []string{"536870912\n", "max\n"} {
		os.WriteFile(file, []byte(content), 0o644)
		fmt.Printf("memory.max=%q: ", strings.TrimSpace(content))

		// GOMEMLIMIT aniq berilgan bo'lsa, unga tegmaymiz
		if os.Getenv("GOMEMLIMIT") != "" {
			fmt.Println("GOMEMLIMIT berilgan")
			continue
		}
		if limit, ok := memLimitFromCgroup(file, 0.9); ok {
			debug.SetMemoryLimit(limit)
			fmt.Println("limit", limit>>20, "MiB qo'yildi")
		} else {
			fmt.Println("limit yo'q, o'zgartirilmadi")
		}
	}
}

