package main

import (
	"cmp"
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"sync/atomic"
	"time"
)

type Config struct {
	Addr, Env       string
	ShutdownTimeout time.Duration
}

func loadConfig(getenv func(string) string) (Config, error) {
	d, err := time.ParseDuration(cmp.Or(getenv("SHUTDOWN_TIMEOUT"), "15s"))
	if err != nil {
		return Config{}, fmt.Errorf("SHUTDOWN_TIMEOUT: %w", err)
	}
	return Config{Addr: cmp.Or(getenv("ADDR"), ":8080"), Env: cmp.Or(getenv("APP_ENV"), "development"), ShutdownTimeout: d}, nil
}

// run — butun dastur: konfiguratsiya, log, health, server va graceful shutdown.
func run(ctx context.Context, getenv func(string) string, out io.Writer, started chan<- string) error {
	cfg, err := loadConfig(getenv)
	if err != nil {
		return err // fail fast
	}

	var ready atomic.Bool
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) { io.WriteString(w, "ok") })
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if !ready.Load() {
			http.Error(w, "tayyor emas", http.StatusServiceUnavailable)
			return
		}
		io.WriteString(w, "tayyor")
	})

	ln, err := net.Listen("tcp", cfg.Addr)
	if err != nil {
		return err
	}
	srv := &http.Server{Handler: mux, ReadHeaderTimeout: 5 * time.Second}
	go srv.Serve(ln)
	ready.Store(true)
	fmt.Fprintln(out, "server tayyor, env:", cfg.Env)
	started <- "http://" + ln.Addr().String()

	<-ctx.Done() // haqiqiy dasturda: signal.NotifyContext(..., syscall.SIGTERM)
	ready.Store(false)
	fmt.Fprintln(out, "to'xtatish boshlandi, timeout:", cfg.ShutdownTimeout)
	sctx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
	defer cancel()
	return srv.Shutdown(sctx)
}

func main() {
	env := map[string]string{"ADDR": "127.0.0.1:0", "APP_ENV": "production", "SHUTDOWN_TIMEOUT": "10s"}
	ctx, stop := context.WithCancel(context.Background())
	started, done := make(chan string), make(chan error)
	go func() { done <- run(ctx, func(k string) string { return env[k] }, os.Stdout, started) }()

	base := <-started
	for _, path := range []string{"/healthz", "/readyz"} {
		resp, _ := http.Get(base + path)
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Println(path, resp.StatusCode, string(body))
	}
	stop() // docker stop -> SIGTERM
	fmt.Println("run qaytardi:", <-done)
}
